"""Islamiat (Ikhtiari) XII PDF67: pp.124–125 — ahadith 31 (explanation), 32, 33. Run: python class12_iski_page067.py"""
from class12_iski_common import BOOK, Builder, rec, P, AR


def p67():
    b = Builder()
    b.h('Explanation', 'تشریح', 'تشریح')
    P(b, [('In this blessed hadith a very great and bad social evil has been mentioned with utmost clarity. He ﷺ, stating the definition of backbiting, said that backbiting is that someone mentions such a thing of his brother in his absence which, if he heard it, he would dislike. Some people think that perhaps a thing which is in someone does not count as backbiting, because it is a statement of fact. He ﷺ made it clear that this very thing is backbiting, and if that thing is not in someone, then it will not be backbiting but rather slander.', 'اس حدیثِ مبارکہ میں ایک بہت بڑی اور بُری معاشرتی برائی کا نہایت صراحت کے ساتھ ذکر کیا گیا ہے۔ آپ صلی اللہ علیہ وآلہٖ وسلم نے غیبت کی تعریف بیان کرتے ہوئے ارشاد فرمایا کہ غیبت یہ ہے کہ کوئی اپنے بھائی کی ایسی بات کا اس کی غیر موجودگی میں ذکر کرے، جسے وہ سن لے تو برا منائے۔ بعض لوگ سمجھتے ہیں کہ شاید جو بات کسی کے اندر ہو وہ غیبت میں شمار نہیں ہوتی کیونکہ وہ تو حقیقتِ حال ہوتی ہے۔ آپؐ نے واضح فرما دیا کہ یہی تو غیبت ہے اور اگر وہ بات کسی کے اندر نہ ہو تو پھر وہ غیبت نہیں ہوگی بلکہ بہتان ہوگا۔', 'په دې مبارک حدیث کې یوه ډېره لویه او بده ټولنیزه بدي په ډېر وضاحت یاده شوې. هغه ﷺ د غیبت تعریف بیان کړ او وې فرمایل: غیبت دا ده چې څوک د خپل ورور په نه شتون کې د هغه داسې خبره یاده کړي چې که یې واوري، بد به یې ګڼي. ځینې خلک ګڼي چې ښايي هغه خبره چې په چا کې وي، په غیبت کې نه شمېرل کېږي، ځکه هغه خو حقیقت دی. هغه ﷺ روښانه کړه چې همدا غیبت دی، او که هغه خبره په چا کې نه وي، نو بیا غیبت نه بلکې تهمت دی.'),
          ('Backbiting has been called a major sin. The Wise Quran has given the example of one who backbites as that of the person who eats the flesh of his dead brother.', 'غیبت کو گناہِ کبیرہ کہا گیا ہے۔ قرآنِ حکیم نے غیبت کرنے والے کی مثال اس شخص کی سی دی ہے جو اپنے مرے ہوئے بھائی کا گوشت کھائے۔', 'غیبت لویه ګناه بلل شوې. قرآن حکیم د غیبت کوونکي مثال د هغه چا په څېر ورکړی چې د خپل مړه ورور غوښه خوري.'),
          ('We should always keep ourselves clean of this evil act. If someone tries to backbite someone in front of us, we should stop him, and if he does not stop, we should go away from there. From backbiting, hatreds and disorder alone are born; reform never comes about.', 'ہمیں چاہیے کہ ہم اس برے فعل سے ہمیشہ اپنا دامن صاف رکھیں۔ اگر کوئی ہمارے سامنے کسی کی غیبت کرنے کی کوشش کرے تو اسے روک دیں اور اگر وہ نہ رکے تو وہاں سے چلے جائیں۔ غیبت سے نفرتیں اور فساد ہی جنم لیتا ہے کبھی اصلاح نہیں ہوتی۔', 'موږ باید تل له دې بد عمل خپل لمن پاکه وساتو. که څوک زموږ مخې ته د چا د غیبت هڅه وکړي، منع یې کړو، او که منع نشي، له هغه ځایه لاړ شو. له غیبت یوازې کرکې او فساد زېږي؛ هېڅکله اصلاح نه کېږي.')])
    b.h('Hadith no. 32', 'حدیث نمبر 32', 'حدیث نمبر ۳۲')
    AR(b, 'عَنْ سَهْلِ بْنِ مُعَاذٍ عَنْ اَبِيْهِ رَضِيَ اللّٰهُ عَنْهُمَا اَنَّ رَسُوْلَ اللّٰهِ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ قَالَ مِنَ الْعِبَادِ عِبَادٌ لَا يُكَلِّمُهُمُ اللّٰهُ يَوْمَ الْقِيٰمَةِ وَلَا يُزَكِّيْهِمْ وَلَا يُطَهِّرُهُمْ وَلَا يَنْظُرُ اِلَيْهِمْ قَالُوْا: مَنْ اُولٰٓئِكَ يَا رَسُوْلَ اللّٰهِ (صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ) قَالَ: اَلْمُتَبَرِّئُ مِنْ وَّالِدَيْهِ رَغْبَةً عَنْهُمَا وَالْمُتَبَرِّئُ مِنْ وَّلَدِهٖ، وَرَجُلٌ اَنْعَمَ عَلَيْهِ قَوْمٌ فَكَفَرَ نِعْمَتَهُمْ وَتَبَرَّاَ مِنْهُمْ', 'الطبرانی، المعجم الکبیر')
    b.p('Translation: Sahl bin Mu\'adh narrates from his father that the Noble Prophet ﷺ said: Among the servants are such servants with whom Allah the Exalted will not speak on the Day of Judgement, nor purify them, nor look towards them. He ﷺ was asked who they would be. He ﷺ said: one who disowns his parents, out of aversion to them …', 'ترجمہ: سہل بن معاذ اپنے والد سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وآلہٖ وسلم نے فرمایا: بندوں میں سے اس بندے سے قیامت کے دن اللہ تعالیٰ نہ کلام کریں گے اور نہ اسکو پاک کریں گے اور نہ اسکی طرف دیکھیں گے۔ آپ صلی اللہ علیہ وآلہٖ وسلم سے پوچھا گیا وہ کون ہوگا؟ آپؐ نے فرمایا: جو اپنے والدین سے بری ہو جاتا ہے ان', 'ژباړه: سهل بن معاذ له خپل پلار روایت کوي چې نبي ﷺ وفرمایل: په بندګانو کې داسې بندګان شته چې الله تعالی به د قیامت په ورځ ورسره خبرې نه کوي، نه به یې پاکوي او نه به ورته ګوري. له هغه ﷺ وپوښتل شول چې هغوی به څوک وي؟ هغه ﷺ وفرمایل: هغه څوک چې له خپل مور و پلار بېزاره شي، له هغوی …')
    r1 = rec(b, 2, 124, 67, [124])
    t = Builder()
    t.p('… with disinclination; and one who disowns his children; and that man upon whom his people have favours, and he denies them and disowns them.', 'سے بے رغبتی کرتے ہوئے اور وہ جو اپنے بچوں سے بری ہو جاتا ہے۔ اور وہ آدمی جس پر اس کی قوم کے احسانات ہیں اور وہ اس کا انکار کرتا ہے اور ان سے بری ہو جاتا ہے۔', '… په بې‌رغبتۍ؛ او هغه څوک چې له خپلو ماشومانو بېزاره شي؛ او هغه سړی چې د خپل قوم احسانونه پرې وي، او هغه یې انکار کوي او ترې بېزاره کېږي.')
    t.h('Explanation', 'تشریح', 'تشریح')
    P(t, [('In this blessed hadith that unfortunate person has been mentioned who does not fulfil the rights of parents, the rights of children and the rights of the nation. Unfortunately in our society too such individuals are found who do not treat their parents well, and in their old age become fed up with them; or who do not care about the rights of their children — they do not look after their needs, do not care about their education and upbringing, and keep ignoring them. Moreover there are such persons too who keep using the resources of the country and nation, but when the time of serving the country and nation comes, they go away, or begin to think that the country and nation have no favour on them; this is only their own labour and struggle.', 'اس حدیثِ مبارکہ میں حقوقِ والدین، حقوقِ اولاد اور قوم کے حقوق ادا نہ کرنے والے بدنصیب شخص کا ذکر کیا گیا ہے۔ بدقسمتی سے ہمارے معاشرے میں بھی ایسے افراد مل جاتے ہیں جو والدین سے حسنِ سلوک نہیں کرتے اور ان کے بڑھاپے میں ان سے بیزار ہو جاتے ہیں۔ یا جو اپنی اولاد کے حقوق کا خیال نہیں کرتے۔ ان کی ضروریات کا خیال نہیں رکھتے، ان کی تعلیم و تربیت کا خیال نہیں کرتے اور انہیں نظر انداز کرتے رہتے ہیں۔ نیز ایسے شخص بھی ہیں جو ملک و قوم کے وسائل استعمال کرتے رہتے ہیں لیکن جب ملک و قوم کی خدمت کا وقت آتا ہے تو دور چلے جاتے ہیں یا یہ سمجھنے لگتے ہیں کہ ملک و قوم کا ان پر کوئی احسان نہیں ہے یہ تو ان کی اپنی محنت اور جدوجہد ہے۔', 'په دې مبارک حدیث کې د هغه بدبخته کس یادونه شوې چې د مور و پلار حقونه، د اولاد حقونه او د قوم حقونه نه ادا کوي. له بده مرغه زموږ په ټولنه کې هم داسې کسان موندل کېږي چې له مور و پلار سره ښه چلند نه کوي او د هغوی په زړښت کې ترې ستړي کېږي؛ یا د خپل اولاد د حقونو پام نه ساتي — د اړتیاوو پام یې نه ساتي، د زده‌کړې او روزنې پام یې نه کوي او له پامه یې غورځوي. همداسې داسې کسان هم شته چې د هېواد او قوم سرچینې کاروي، خو کله چې د هېواد او قوم د خدمت وخت راشي، لرې ځي، یا ګڼي چې هېواد او قوم پرې هېڅ احسان نه لري؛ دا خو د دوی خپل زیار او هڅه ده.'),
          ('About such people the blessed saying of the Noble Prophet ﷺ is that on the Day of Judgement Allah will neither look towards such people, nor purify them, nor speak to them. The meaning of this is that such people will remain deprived of the mercy of Allah. Those who will be deprived of the mercy and kind glance of Allah — their abode will be very bad. Therefore we should serve our parents as much as possible, fulfil the rights of children, and be of use to our country and nation.', 'ایسے لوگوں کے بارے میں نبی اکرم صلی اللہ علیہ وآلہٖ وسلم کا ارشادِ گرامی ہے کہ قیامت والے دن ایسے لوگوں کی طرف نہ تو اللہ دیکھے گا، نہ انہیں پاک کرے گا اور نہ ان سے ہم کلام ہوگا۔ اس کا مطلب یہی ہے کہ ایسے لوگ اللہ کی رحمت سے محروم رہیں گے۔ جو لوگ اللہ کی رحمت اور نظرِ کرم سے محروم ہوں گے ان کا ٹھکانہ بہت برا ہوگا۔ لہٰذا ہمیں چاہیے کہ ہم اپنے والدین کی زیادہ سے زیادہ خدمت کریں، اولاد کے حقوق ادا کریں اور اپنے ملک و قوم کے کام آئیں۔', 'د داسې خلکو په اړه د نبي اکرم ﷺ مبارک ارشاد دی چې د قیامت په ورځ به الله نه داسې خلکو ته ګوري، نه به یې پاکوي او نه به ورسره خبرې کوي. مطلب یې دا دی چې داسې خلک به د الله له رحمت بې‌برخې وي. کوم خلک چې د الله له رحمت او مهربانه نظره بې‌برخې وي، ځای به یې ډېر بد وي. نو موږ باید د خپل مور و پلار تر ډېره ډېر خدمت وکړو، د اولاد حقونه ادا کړو او د خپل هېواد او قوم په کار راشو.')])
    t.h('Hadith no. 33', 'حدیث نمبر 33', 'حدیث نمبر ۳۳')
    AR(t, 'وَعَنْ عَبْدِ اللّٰهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللّٰهُ عَنْهُمَا عَنِ النَّبِيِّ ﷺ قَالَ: رِضَى اللّٰهِ فِيْ رِضَى الْوَالِدَيْنِ، وَسَخَطُ اللّٰهِ فِيْ سَخَطِ الْوَالِدَيْنِ', 'سنن الترمذی کتاب البر والصلۃ: حدیث نمبر ۱۹۰۰')
    t.p('Translation: Abdullah bin Amr bin As (may Allah be pleased with him) narrates that the Noble Prophet ﷺ said: The pleasure of Allah lies in the pleasure of the parents, and the displeasure of Allah lies in the displeasure of the parents.', 'ترجمہ: عبداللہ بن عمرو بن عاصؓ روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وآلہٖ وسلم نے فرمایا اللہ کا راضی ہونا ماں باپ کے راضی ہونے میں ہے اور اللہ کا ناراض ہونا ماں باپ کے ناراض ہونے میں ہے۔', 'ژباړه: عبدالله بن عمرو بن عاص رضي الله عنه روایت کوي چې نبي کریم ﷺ وفرمایل: د الله رضا د مور و پلار په رضا کې ده، او د الله ناخوښي د مور و پلار په ناخوښۍ کې ده.')
    BOOK.save(67, [(2, r1), (2, rec(t, 2, 125, 67, [125]))], issues=[{'id': 'iski12-pdf067', 'unit': 2, 'printedPage': 124,
               'description': 'Student handwriting (words over the explanation of hadith 31, note beside the translation of hadith 32, signature below p.124) excluded.'}])


if __name__ == '__main__':
    p67()
